  "title": "Usar since e for",
  "rule": "Em inglês, usamos 'for' para indicar a duração de um período e 'since' para marcar o ponto de início. Como em português usamos 'desde' para ambos os casos, você acaba confundindo as duas palavras.",
  "contrast": [
    {
      "label": "for + duração",
      "example": "for two years"
    },
    {
      "label": "since + início",
      "example": "since 2015"
    }
  ],
  "drill": [
    {
      "sentence": "We have lived in this city ___ five years.",
      "answer": "for",
      "options": [
        "for",
        "since",
        "ago"
      ],
      "feedback": "Usamos 'for' porque 'five years' é a duração total do tempo."
    },
    {
      "sentence": "I have been waiting for the bus ___ 8 o'clock.",
      "answer": "since",
      "options": [
        "since",
        "for",
        "ago"
      ],
      "feedback": "Usamos 'since' pois '8 o'clock' é o ponto exato em que a espera começou."
    },
    {
      "sentence": "She has worked at the bank ___ last July.",
      "answer": "since",
      "options": [
        "for",
        "since",
        "ago"
      ],
      "feedback": "'Last July' é o ponto inicial da ação, por isso usamos 'since'."
    },
    {
      "sentence": "They have been studying English ___ a long time.",
      "answer": "for",
      "options": [
        "since",
        "for",
        "ago"
      ],
      "feedback": "'A long time' descreve a extensão do período, logo usamos 'for'."
    },
    {
      "sentence": "My parents have been married ___ 1990.",
      "answer": "since",
      "options": [
        "for",
        "since",
        "ago"
      ],
      "feedback": "Como '1990' é uma data específica de início, usamos 'since'."
    }
  ]
}
